      return false;
    }
    writeGridSize(storageRef.current, game.board.size);
    replace(game);
    return true;
  }

  function loadSnapshot(text: string): boolean {
    syncClock();
    const game = decodeSnapshot(text);
    if (!game) {
      commit(announce(viewRef.current, "Invalid snapshot."));
      return false;
    }
    const completed = isWon(game);
    writeGridSize(storageRef.current, game.board.size);
