import { useEffect, useRef, useState } from "react";
import { Board, type BoardHandle } from "./board/Board.tsx";
import { DealControls } from "./controls/DealControls.tsx";
import { ReproductionControls } from "./controls/ReproductionControls.tsx";
import { GameStatus } from "./status/GameStatus.tsx";
import { isWon } from "./state.ts";
import { useGameSession } from "./session/useGameSession.ts";
import { formatTime } from "./timing.ts";
import "./Game.css";

export function Game(): React.JSX.Element {
  const session = useGameSession();
  const boardRef = useRef<BoardHandle>(null);
  const [boardCode, setBoardCode] = useState(session.game.board.code);
  const dealId = session.dealId;
  const currentCode = session.game.board.code;
  const complete = isWon(session.game);

  useEffect(() => {
    setBoardCode(currentCode);
  }, [dealId, currentCode]);

  function resume(): void {
    boardRef.current?.focusRemembered();
    session.resume();
  }

  function loadBoard(): void {
    session.loadBoard(boardCode);
  }

  function loadSnapshot(text: string): void {
    session.loadSnapshot(text);
  }

  return (
    <main className="neon-app">
      <header className="neon-header">
        <div>
          <p className="neon-eyebrow">A quiet game of memory</p>
          <h1>Neon Pairs</h1>
          <p className="neon-intro">Find every pair. Arrow keys move; Enter or Space turns a card over.</p>
        </div>
      </header>
      {session.announcement ? (
        <div className="neon-screen-reader-status" role="status" aria-live="polite" aria-atomic="true">
          <span key={session.announcement.id}>{session.announcement.text}</span>
        </div>
      ) : (
        <div className="neon-screen-reader-status" role="status" aria-live="polite" aria-atomic="true">
          <span />
        </div>
      )}
      <GameStatus game={session.game} bestMoves={session.bestMoves} />
      {complete ? (
        <section className={`neon-win-banner${session.celebrating ? " neon-win-banner--pulse" : ""}`}>
          <h2>All pairs found!</h2>
          <p>Finished in {session.game.moves} moves and {formatTime(session.game.elapsedMs)}.</p>
        </section>
      ) : null}
      <div className="neon-game-layout">
        <section className="neon-board-section" aria-labelledby="neon-board-heading">
          <div className="neon-section-heading">
            <h2 id="neon-board-heading">Find the pairs</h2>
            <p>Matched cards stay open. A miss closes after a short pause.</p>
          </div>
          <Board ref={boardRef} game={session.game} paused={session.paused} dealId={session.dealId}
            onActivate={session.activateCard} />
        </section>
        <aside className="neon-tools">
          <DealControls size={session.game.board.size} resumeVisible={session.paused}
            onSizeChange={session.changeSize} onNewGame={session.newGame} onRestart={session.restart}
            onResume={resume} />
          <ReproductionControls boardCode={boardCode} announcement={session.announcement}
            onBoardCodeChange={setBoardCode} onLoadBoard={loadBoard} onLoadSnapshot={loadSnapshot}
            onExportSnapshot={session.exportSnapshot} />
        </aside>
      </div>
      <footer className="neon-footer">Every face has its own shape, marker, and fill.</footer>
    </main>
  );
}
import { useState } from "react";
import type { SessionAnnouncement } from "../session/types.ts";
import "./controls.css";

type ReproductionControlsProps = Readonly<{
  boardCode: string;
  announcement: SessionAnnouncement | null;
  onBoardCodeChange(code: string): void;
  onLoadBoard(): void;
  onLoadSnapshot(text: string): void;
  onExportSnapshot(): string;
}>;

function visibleControlStatus(announcement: SessionAnnouncement | null): string {
  switch (announcement?.text) {
    case "Invalid board code.":
    case "Invalid snapshot.":
    case "Loaded snapshot. Select Resume to continue.":
    case "Loaded completed snapshot.":
      return announcement.text;
    default:
      return "";
  }
}

export function ReproductionControls({
  boardCode, announcement, onBoardCodeChange, onLoadBoard, onLoadSnapshot, onExportSnapshot,
}: ReproductionControlsProps): React.JSX.Element {
  const [snapshotText, setSnapshotText] = useState("");
  const status = visibleControlStatus(announcement);
  const invalidCode = announcement?.text === "Invalid board code.";
  const invalidSnapshot = announcement?.text === "Invalid snapshot.";

  return (
    <details className="neon-reproduction">
      <summary>Reproduce a game</summary>
      <div className="neon-reproduction-content">
        <label className="neon-field" htmlFor="neon-board-code">
          <span>Board code</span>
          <input id="neon-board-code" type="text" value={boardCode} maxLength={32}
            autoComplete="off" autoCapitalize="none" spellCheck={false}
            aria-invalid={invalidCode} aria-describedby={invalidCode ? "neon-control-status" : undefined}
            onChange={(event) => onBoardCodeChange(event.currentTarget.value)} />
        </label>
        <button className="neon-button neon-board-load" type="button" onClick={onLoadBoard}>
          Load board
        </button>
        <label className="neon-field neon-snapshot-field" htmlFor="neon-snapshot-json">
          <span>Snapshot JSON</span>
          <textarea id="neon-snapshot-json" rows={7} maxLength={65_536} value={snapshotText}
            aria-invalid={invalidSnapshot} aria-describedby={invalidSnapshot ? "neon-control-status" : undefined}
            onChange={(event) => setSnapshotText(event.currentTarget.value)} />
        </label>
        <div className="neon-snapshot-actions">
          <button className="neon-button" type="button" onClick={() => setSnapshotText(onExportSnapshot())}>
            Export snapshot
          </button>
          <button className="neon-button" type="button" onClick={() => onLoadSnapshot(snapshotText)}>
            Load snapshot
          </button>
        </div>
        <p className="neon-control-status" id="neon-control-status">{status}</p>
      </div>
    </details>
  );
}
