import { mkdirSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { expect, test } from "@playwright/test";
import { cards, CODE_4, MATCHES } from "./helpers.ts";

async function moveTo(page: import("@playwright/test").Page, from: number, to: number): Promise<number> {
  const side = 4;
  let current = from;
  let column = current % side;
  const targetColumn = to % side;
  while (column < targetColumn) { await page.keyboard.press("ArrowRight"); current += 1; column += 1; }
  while (column > targetColumn) { await page.keyboard.press("ArrowLeft"); current -= 1; column -= 1; }
  while (current < to) { await page.keyboard.press("ArrowDown"); current += side; }
  while (current > to) { await page.keyboard.press("ArrowUp"); current -= side; }
  await expect(cards(page).nth(to)).toBeFocused();
  return current;
}

