    await expect(cards(page).nth(0)).toHaveAttribute("aria-label", "Row 1, column 1, closed");
    expect(externalRequests).toEqual([]);
    expect(errors).toEqual([]);
    expect(await page.locator("audio,video").count()).toBe(0);
  } finally {
    await context.close();
  }
});

